var builder = WebApplication.CreateBuilder(args);

// [Fix 4] Captive dependency: scoped IUserService was captured by singleton CacheService.
// .NET 9 enables ValidateScopes in development by default, which throws at startup.
// Fix: register CacheService as scoped so it doesn't outlive its dependency.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// [Fix 1] .NET 9 HttpClientFactory uses SocketsHttpHandler by default.
// Casting to HttpClientHandler throws InvalidCastException at runtime.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// [Fix 5] .NET 9 HttpClientFactory redacts all header values in Trace-level logs.
// Explicitly allowlist non-sensitive headers you need to see when debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Forwarded-For"
        && h != "X-Request-Id"
        && h != "Content-Type"
        && h != "Accept"));

// [Fix 2] .NET 9 ForwardedHeaders middleware ignores X-Forwarded-* from unknown proxies.
// You must register your reverse-proxy address in KnownProxies or KnownNetworks.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: add your actual proxy address, e.g.:
    // options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

